{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "Mithramycin, the closest-scoring glycosylated polyketide, showed a CSF:plasma ratio of only 0.12 in monkeys and little brain uptake, supporting poor CNS access for large polar glycosides like the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Digitoxin, a sugar-rich cardiac glycoside, had CSF/plasma ratios of 0.01-0.03 in dogs, indicating that glycoside-type natural products are effectively excluded from the CNS.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Paclitaxel, a P-gp substrate anticancer natural product, was pumped out of the brain and showed very low brain concentrations after i.v. dosing; the query's anthracycline aminosugar is also a known P-gp substrate, so efflux would limit CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "In humans, paclitaxel CSF exposure was at most about 8% of plasma concentrations, confirming poor CNS access for P-gp substrate anticancer drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "CMT-3, a lipophilic tetracycline, accumulated in rat brain at 4 µg/g, showing that some large polycyclic drugs can achieve brain exposure; however, the query is much more polar and glycosylated, so this positive result has limited transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted fail: the query is a large, polar, zwitterionic anthracycline glycoside with high TPSA and H-bond counts; direct CNS measurements in structurally related glycosides and P-gp substrate anticancer drugs consistently show poor brain/CSF penetration, and the physicochemical prior indicates low passive permeability and likely efflux.",
  "evidence_gaps": [
    "No direct daunorubicin or doxorubicin brain/CSF measurement was present in the evidence set; transfer relies on structurally related glycosides and P-gp substrates.",
    "Morgan similarities are low (<0.25), so quantitative transfer is uncertain.",
    "No transporter phenotype (e.g., P-gp knockout or inhibitor study) was measured for the query itself."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

